import '@servicenow/sdk/global'
import { StringColumn, BooleanColumn, IntegerColumn } from '@servicenow/sdk/core'
import { Flow, wfa, action, FlowArray, FlowObject } from '@servicenow/sdk/automation'
import { trigger } from '@servicenow/sdk/automation'

// Flow 1: Simple FlowArray with forEach
Flow(
    {
        $id: Now.ID['flow_label_cache_foreach_simple'],
        name: 'Flow - Label Cache ForEach Simple',
        description: 'Tests label cache with forEach over simple FlowArray',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
        flowVariables: {
            departments: FlowArray({
                mandatory: true,
                label: 'Departments',
                elementType: FlowObject({
                    fields: {
                        deptName: StringColumn({ mandatory: true, label: 'Deptname', max_length: 100 }),
                        deptCode: StringColumn({ mandatory: true, label: 'Deptcode', max_length: 10 }),
                        headCount: IntegerColumn({ mandatory: true, label: 'Headcount', max_length: 5 }),
                    },
                    mandatory: true,
                    label: 'Department',
                }),
                childName: 'department',
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['foreach_simple_trigger'] },
        {
            table: 'sys_user',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_setting: 'both',
            run_when_user_list: [],
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        wfa.flowLogic.forEach(
            wfa.dataPill(params.flowVariables.departments, 'array.object'),
            { $id: Now.ID['foreach_departments'], annotation: 'Loop departments' },
            (item) => {
                wfa.action(
                    action.core.log,
                    { $id: Now.ID['log_dept_info'] },
                    {
                        log_message: `Department: ${wfa.dataPill(item.deptName, 'string')}, Code: ${wfa.dataPill(item.deptCode, 'string')}, Count: ${wfa.dataPill(item.headCount, 'integer')}`,
                        log_level: 'info',
                    }
                )
            }
        )
    }
)

